WITH scored AS (SELECT *, COUNT(amount) OVER w_ordered AS account_id_count_amount, ROW_NUMBER() OVER (PARTITION BY txn_type, account_id ORDER BY txn_time DESC, id) AS row_seq, ROUND(amount / SUM(amount) OVER (PARTITION BY txn_type), 4) AS amount_share FROM transactions WHERE amount > 1900 WINDOW w_ordered AS (PARTITION BY account_id, merchant)) SELECT id, txn_type, amount, txn_time, merchant, is_flagged, account_id_count_amount, row_seq FROM scored ORDER BY txn_time DESC;
